     3	/// File ▸ Re-lay Captions for This Canvas (road map "creator-jobs" VR4a, spec §11 VR-45): the
     4	/// word caption tracks of the container being edited — the timeline, or the open nest at the
     5	/// nest's size — re-paged on its canvas from their own words (`CaptionRelayout.plan`, VR-40)
     6	/// as one undo step "Re-lay Captions". No sheet of its own: an informational sheet names each
     7	/// caption track kept as placed, and none appears when every track was re-laid.
     8	/// `relay_captions` mirrors it (`AgentServer+VerticalVersion.swift`).
     9	extension EditorViewController {
    10	
    11	    @objc func relayCaptions(_ sender: Any?) {
    12	        guard let document, view.window?.attachedSheet == nil,
    13	            !ScreenRecorder.shared.isRecording
    14	        else {
    15	            NSSound.beep()
    16	            return
    17	        }
    18	        let planned: (ops: [ReelOp], outcome: CaptionRelayout.Outcome)
    19	        do {
    20	            planned = try CaptionRelayout.plan(document.editedProject)
    21	        } catch {
    22	            showRelayCaptionsNotice(error.localizedDescription)
    23	            return
    24	        }
    25	        guard !planned.ops.isEmpty else {
    26	            if let nothing = CaptionRelayout.noticeText(planned.outcome) {
    27	                showRelayCaptionsNotice(nothing)
    28	            } else {
    29	                NSSound.beep()
    30	            }
    31	            return
    32	        }
    33	        document.performGroupedEdit(CaptionRelayout.actionName, planned.ops)
    34	        if let text = CaptionRelayout.noticeText(planned.outcome) {
    35	            showRelayCaptionsNotice(text)
    36	        }
    37	    }
    38	
    39	    /// An informational sheet on the editor's window: the notice's first line as its message,
    40	    /// the kept tracks' lines as its informative text (`showShortcutOverlayNotice`'s shape);
    41	    /// nothing with no window or a sheet already up.
    42	    private func showRelayCaptionsNotice(_ text: String) {
    43	        guard let window = view.window, window.attachedSheet == nil else { return }
    44	        var lines = text.components(separatedBy: "\n")
    45	        let alert = NSAlert()
    46	        alert.alertStyle = .informational
    47	        alert.messageText = lines.removeFirst()
    48	        alert.informativeText = lines.joined(separator: "\n")
    49	        alert.beginSheetModal(for: window, completionHandler: nil)
    50	    }
    51	
    52	    /// The menu arm, answered from `validateUserInterfaceItem`'s default case; nil for any
    53	    /// other action. On with a document, no sheet on the window, no recording running and at
    54	    /// least one recognised caption track in the container being edited; allowed inside a
    55	    /// nest.
    56	    func validateRelayCaptionsAction(_ action: Selector) -> Bool? {
    57	        guard action == #selector(relayCaptions(_:)) else { return nil }
    58	        guard let document, view.window?.attachedSheet == nil,
    59	            !ScreenRecorder.shared.isRecording
    60	        else { return false }
    61	        return !CaptionRelayout.survey(document.editedProject.snapshot).recognised.isEmpty
    62	    }
    63	}
