  184 recipe_words.rs
  1	//! What a timed text page SHOWS at one instant: [`Words`] — how many of its
  2	//! words have started, how far the newest one's pop has got, and how far
  3	//! its pill's glide, its fill and the page's dim have got — the five
  4	//! computed keys `recipe_text.rs`'s `text_source` emits on every text layer
  5	//! as `word`, `word_pop`, `word_glide`, `word_fill` and `word_dim` (spec
  6	//! §7.3; road map 8 §5b; spec §11 W-13 for the last three).
  7	//!
  8	//! The recipe carries a computed ANSWER, never the timings (spec §11, W-4):
  9	//! `text.words` is stripped from the description the renderer receives, as
 10	//! `text.animation` is, and these five numbers are the whole of what it is
 11	//! told. The renderer derives the rest from `word` — the active word is
 12	//! token `word − 1`, the spoken ones are before it, the upcoming ones from
 13	//! `word` on, and a gliding pill comes from token `word − 2` — with its own
 14	//! tokenizer, and no offset and no second index crosses the seam (the two
 15	//! tokenizers agree on the COUNT, which is the only number shared).
 16	//!
 17	//! A new module rather than more of `recipe_text.rs` because that file is a
 18	//! reveal and a burn-in and stood at 510, and because this is a second,
 19	//! independent account of a text layer's content over time: W-5 says the
 20	//! two do not compose, so a styled page is a WHOLE reveal and only this
 21	//! module speaks for it.
 22	
 23	use serde_json::{Map, Value};
 24	
 25	use crate::evaluate::number;
 26	use crate::model::TextProps;
 27	use crate::model_words::token_count;
 28	use crate::recipe_text::ramp;
 29	use crate::time::Ticks;
 30	
 31	/// How long the active word's pop takes to settle into `active_scale`:
 32	/// 0.12 s (road map 8 §8). Long enough to read as a pop, short enough that
 33	/// a page re-rasterizes for a handful of frames after each word start and
 34	/// then hits the texture cache again.
 35	pub(crate) const WORD_POP: Ticks = 72_000;
 36	
 37	/// How long a pill takes to slide to the active word: 0.2 s, or the time
 38	/// until the next word starts when that is sooner, so the plate has always
 39	/// arrived before it must leave again.
 40	pub(crate) const WORD_GLIDE: Ticks = 120_000;
 41	
 42	/// The longest a word takes to fill: 0.6 s (spec §11 W-13, the owner's
 43	/// choice — a chosen number, not a measured one). A word's `end` is not
 44	/// always where it stopped being said: the on-device engine's word ranges
 45	/// tile the audio, so the last word before a pause is stored as lasting
 46	/// through most of the pause (road map 8 measured a 1.57 s silence stored as
 47	/// a 0.30 s gap), and uncapped it would crawl for over a second.
 48	pub(crate) const WORD_FILL_MAX: Ticks = 360_000;
 49	
 50	/// How long the page takes to dim at the start of a pause, and to come back
 51	/// before the next word: 0.1 s each way.
 52	pub(crate) const WORD_DIM: Ticks = 60_000;
 53	
 54	/// The shortest pause that dims: 0.25 s — the pager's own word gap (W-7).
 55	/// Under it a pause is an ordinary gap between two words of a sentence, and
 56	/// dimming there would flicker.
 57	pub(crate) const WORD_DIM_GAP: Ticks = 150_000;
 58	
 59	/// The five computed word keys of one text layer at one instant.
 60	#[derive(Debug, Clone, Copy, PartialEq)]
 61	pub(crate) struct Words {
 62	    /// How many words have started, 0 to n; `None` when the page is not
 63	    /// word-timed (no `word_style`, empty `words`, or a count mismatch).
 64	    pub(crate) word: Option<usize>,
 65	    /// 0..1 through the active word's pop; `None` before the first word
 66	    /// starts, or when `active_scale` is 1.0 and there is nothing to pop.
 67	    pub(crate) pop: Option<f64>,
 68	    /// 0..1 through the pill's slide from token `word − 2` to the active
 69	    /// one; `None` unless `active_pill.glide` is set and a second word has
 70	    /// started — a page's first word has no word to slide from.
 71	    pub(crate) glide: Option<f64>,
 72	    /// 0..1 through the active word's fill, holding 1.0 after; `None`
 73	    /// unless `active_fill` is set and a word has started.
 74	    pub(crate) fill: Option<f64>,
 75	    /// 0..1 into the dim of a pause; `None` unless `pause_dim` is above 0.
