 79	impl Words {
 80	    /// A layer that is not word-timed: every key null.
 81	    pub(crate) const NONE: Words = Words {
 82	        word: None,
 83	        pop: None,
 84	        glide: None,
 85	        fill: None,
 86	        dim: None,
 87	    };
 88	
 89	    /// The word keys `clip_t` ticks into a clip that is `duration` long.
 90	    ///
 91	    /// Total, and it assumes nothing about ORDER. The patch door refuses a
 92	    /// list whose starts decrease, but it is not the only writer: the file
 93	    /// reader stores `words` whole
 94	    /// (`edit_props.rs`'s `normalise_and_check_group` doc), so an unsorted
 95	    /// list, or a start of `i64::MIN`, reaches here. `word` is therefore a
 96	    /// COUNT of started words rather than a search, every other word is
 97	    /// read by `get`, every subtraction saturates and every division is
 98	    /// `recipe_text.rs`'s `ramp`, which answers 0..1 for any two ticks. A
 99	    /// count mismatch (which only an action switching `content` can
100	    /// produce, W-6) degrades to [`Words::NONE`]: the page draws static
101	    /// rather than highlighting the wrong token.
102	    pub(crate) fn of(text: &TextProps, clip_t: Ticks, duration: Ticks) -> Words {
103	        let style = match &text.word_style {
104	            Some(style) => style,
105	            None => return Words::NONE,
106	        };
107	        let count = text.words.len();
108	        if count == 0 || count != token_count(&text.content) {
109	            return Words::NONE;
110	        }
111	        // Equal starts are legal (two engine words snapped to one frame),
112	        // and both count: the later of them is the active word, which is
113	        // "the later one wins that frame".
114	        let word = text.words.iter().filter(|w| w.start <= clip_t).count();
115	        let active = word.checked_sub(1).and_then(|i| text.words.get(i));
116	        let next = text.words.get(word);
117	        let pop = match active {
118	            Some(active) if style.active_scale != 1.0 => {
119	                Some(ramp(clip_t.saturating_sub(active.start), WORD_POP))
120	            }
121	            _ => None,
122	        };
123	        // The glide runs from the active word's start, and is over by the
124	        // next word's: a word shorter than `WORD_GLIDE` gets a quicker
125	        // slide rather than a pill that never arrives.
126	        let glides = style.active_pill.is_some_and(|pill| pill.glide);
127	        let glide = match active {
128	            Some(active) if glides && word >= 2 => {
129	                let over = next.map_or(WORD_GLIDE, |next| {
130	                    WORD_GLIDE.min(next.start.saturating_sub(active.start))
131	                });
132	                Some(ramp(clip_t.saturating_sub(active.start), over))
133	            }
134	            _ => None,
135	        };
136	        let fill = match active {
137	            Some(active) if style.active_fill => {
138	                let spoken = active.end.saturating_sub(active.start);
139	                Some(ramp(
140	                    clip_t.saturating_sub(active.start),
141	                    spoken.min(WORD_FILL_MAX),
142	                ))
143	            }
144	            _ => None,
145	        };
146	        let dim = (style.pause_dim > 0.0).then(|| {
147	            // The pause this instant is in runs from the active word's end
148	            // — clip time 0 before the first word — to the next word's
149	            // start — the clip's end after the last.
150	            let from = active.map_or(0, |active| active.end);
151	            let until = next.map_or(duration, |next| next.start);
152	            if clip_t < from || until.saturating_sub(from) < WORD_DIM_GAP {
153	                return 0.0;
154	            }
155	            // A side with no word on it has no ramp: the page opens dim
156	            // before a late first word, and stays dim after the last.
157	            let down = active.map_or(1.0, |_| ramp(clip_t.saturating_sub(from), WORD_DIM));
158	            let up = next.map_or(1.0, |_| ramp(until.saturating_sub(clip_t), WORD_DIM));
159	            down.min(up)
160	        });
161	        Words {
162	            word: Some(word),
163	            pop,
164	            glide,
165	            fill,
166	            dim,
167	        }
168	    }
169	
170	    /// Writes the five keys into `map` — a text layer's `source`, and the
171	    /// object its hash is taken over — in the recipe's order.
172	    pub(crate) fn insert_into(&self, map: &mut Map<String, Value>) {
173	        map.insert("word".to_string(), Value::from(self.word));
174	        let rest = [
175	            ("word_pop", self.pop),
176	            ("word_glide", self.glide),
177	            ("word_fill", self.fill),
178	            ("word_dim", self.dim),
179	        ];
180	        for (key, value) in rest {
181	            map.insert(key.to_string(), value.map_or(Value::Null, number));
182	        }
183	    }
184	}

